An expression tree is a binary tree in which each internal node corresponds to the operator and each leaf node corresponds to the operand so for example expression tree for 3 + ((5 + 9) * 2) would be: Inorder traversal of expression tree produces infix version of given postfix expression (same with postorder traversal it gives postfix expression)Evaluating the expression represented by an expression tree: Let t be the expression treeIf  t is not null then      If t.value is operand then                  Return  t.value      A = solve(t.left)      B = solve(t.right)       // calculate applies operator 't.value'       // on A and B, and returns value      Return calculate(A, B, t.value)Try It YourselfConstruction of Expression Tree: Now for constructing an expression tree, we use a stack. We loop through input expression and do the following for every character. If a character is an operand push that into the stackIf a character is an operator pop two values from the stack make them its child and push the current node again.In the end, the only element of the stack will be the root of an expression tree.Examples:  Input:  A B C*+ D/Output: A + B * C / DThe first three symbols are operands, so create tree nodes and push pointers to them onto a stack as shown below. In the Next step, an operator ‘*’ will going read, so two pointers to trees are popped, a new tree is formed and a pointer to it is pushed onto the stack In the Next step,  an operator ‘+’ will read, so two pointers to trees are popped, a new tree is formed and a pointer to it is pushed onto the stack. Similarly, as above cases first we push 'D' into the stack and then in the last step first, will read '/' and then as previous step topmost element will pop out and then will be right subtree of root  '/' and other nodes will be right subtree.        Final Constructed Expression Tree is: Below is the implementation of the above approach:  
            C++

    // C++ program for expression tree
#include <bits/stdc++.h>
using namespace std;
class node {
public:
    char value;
    node* left;
    node* right;
    node* next = NULL;
    node(char c)
    {
        this->value = c;
        left = NULL;
        right = NULL;
    }
    node()
    {
        left = NULL;
        right = NULL;
    }
    friend class Stack;
    friend class expression_tree;
};
class Stack {
    node* head = NULL;

public:
    void push(node*);
    node* pop();
    friend class expression_tree;
};
class expression_tree {
public:
    void inorder(node* x)
    {
        // cout<<"Tree in InOrder Traversal is: "<<endl;
        if (x == NULL)
            return;
        else {
            inorder(x->left);
            cout << x->value << "  ";
            inorder(x->right);
        }
    }
};

void Stack::push(node* x)
{
    if (head == NULL) {
        head = x;
    }

    // We are inserting here nodes at the top 
    // of the stack [following LIFO principle]
    else {
        x->next = head;
        head = x;
    }
}
node* Stack::pop()
{
    // Popping out the top most[ pointed with head] element
    node* p = head;
    head = head->next;
    return p;
}
int main()
{
    string s = "ABC*+D/";

    // If you  wish take input from user:
    // cout << "Insert Postorder Expression: " << endl;
    // cin >> s;
    Stack e;
    expression_tree a;
    node *x, *y, *z;
    int l = s.length();
    for (int i = 0; i < l; i++) {

        // if read character is operator then popping two
        // other elements from stack and making a binary
        // tree
        if (s[i] == '+' || s[i] == '-' || s[i] == '*'
            || s[i] == '/' || s[i] == '^') {
            z = new node(s[i]);
            x = e.pop();
            y = e.pop();
            z->left = y;
            z->right = x;
            e.push(z);
        }
        else {
            z = new node(s[i]);
            e.push(z);
        }
    }
    cout << " The Inorder Traversal of Expression Tree: ";
    a.inorder(z);
    return 0;
}


