    // Javascript code for the above approach
class Node {
    constructor(value = null, left = null, right = null, next = null) {
        this.value = value;
        this.left = left;
        this.right = right;
        this.next = next;
    }
}

class Stack {
    constructor() {
        this.head = null;
    }

    push(node) {
        if (!this.head) {
            this.head = node;
        } 
        else
        {
         // We are inserting here nodes at 
         // the top of the stack [following LIFO principle]
            node.next = this.head;
            this.head = node;
        }
    }

    pop() {
        if (this.head) {
            let popped = this.head;
            this.head = this.head.next;
            return popped;
        } else {
            throw new Error("Stack is empty");
        }
    }
}

class ExpressionTree {
    inorder(x) {
        if (!x) {
            return;
        }
        this.inorder(x.left);
        console.log(x.value+" ");
        this.inorder(x.right);
    }
}


    let s = "ABC*+D/";
    let stack = new Stack();
    let tree = new ExpressionTree();
    for (let c of s) {
        if (c === "+" || c === "-" || c === "*" || c === "/" || c === "^") {
            let z = new Node(c);
            let x = stack.pop();
            let y = stack.pop();
            z.left = y;
            z.right = x;
            stack.push(z);
        } else {
            stack.push(new Node(c));
        }
    }
    console.log("The Inorder Traversal of Expression Tree: ");
